using System;
using System.Text;

namespace AhoChatA.Music
{
    /// <summary>
    /// 汉字 -> 拼音首字母（A-Z）与排序键。表由 tmp/genpinyin/gen.py 从 pypinyin 生成，
    /// 与 Assets/webui/js/pinyin.js 完全一致，保证 App 与网页端分组/排序结果相同。
    /// 覆盖 CJK 基本区 U+4E00..U+9FFF；表外字符（生僻字/符号）归 '#'。
    /// </summary>
    public static class Pinyin
    {
        private const int Start = 0x4E00;
        private const int End = 0x9FFF;

        private const string Table =
            "#DQDFMSD#####XQBPFDWO##WHLYPCBJCC#DMBZPBZZ#####Z#W###Z####S#####L#######SL##Z####LGTM####GD#####################ATN##HBLTDZLATMMBJ#LX";

        /// <summary>取单个字符的拼音首字母；非汉字英文字母返回自身大写，其余返回 '#'。</summary>
        public static char FirstOf(char c)
        {
            if (c >= 'a' && c <= 'z') return (char)(c - 32);
            if (c >= 'A' && c <= 'Z') return c;
            if (c >= Start && c <= End)
            {
                char v = Table[c - Start];
                return v == '#' ? '#' : v;
            }
            return '#';
        }

        /// <summary>取一个名字的首字母（跳过符号/数字，取第一个可判定字母）；无法判定时返回 '#'。</summary>
        public static char FirstLetter(string name)
        {
            if (string.IsNullOrEmpty(name)) return '#';
            foreach (char c in name.Trim())
            {
                // 数字开头的曲目归 '#'，不要跳到后面的字母（例如 "123abc" 不应算 A）
                if (c >= '0' && c <= '9') return '#';
                char v = FirstOf(c);
                if (v != '#') return v;
            }
            return '#';
        }

        /// <summary>排序键：逐字转拼音首字母（英文小写、数字保留、符号忽略）。用于 A-Z 分组排序。</summary>
        public static string SortKey(string name)
        {
            if (string.IsNullOrEmpty(name)) return "";
            var sb = new StringBuilder(name.Length);
            foreach (char c in name.Trim())
            {
                if (c >= 'A' && c <= 'Z') { sb.Append((char)(c + 32)); continue; }
                if (c >= 'a' && c <= 'z') { sb.Append(c); continue; }
                if (c >= '0' && c <= '9') { sb.Append(c); continue; }
                if (c >= Start && c <= End)
                {
                    char v = Table[c - Start];
                    if (v != '#') sb.Append((char)(v + 32));
                    continue;
                }
                if (c == '#') sb.Append('#');
            }
            return sb.ToString();
        }

        /// <summary>按拼音 A-Z 比较（Ordinal，大小写无关），键相同则回退原字符串。</summary>
        public static int Compare(string a, string b)
        {
            string ka = SortKey(a), kb = SortKey(b);
            int r = string.Compare(ka, kb, StringComparison.Ordinal);
            if (r != 0) return r;
            return string.Compare(a ?? "", b ?? "", StringComparison.CurrentCultureIgnoreCase);
        }
    }
}
